// Renders every BlackLab Desktop view against the phone's snapshot contract
// (snapshot.fixture.json, generated by app/src/test/.../link/SnapshotContractTest.kt from the
// phone's own code). A field the phone renamed or dropped shows up here as "undefined", "NaN",
// "[object Object]", "Invalid Date" or a thrown error instead of a quietly blank panel.
//   node --test desktop/web/tests/
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const here = dirname(fileURLToPath(import.meta.url));
const web = join(here, '..');
const fixture = JSON.parse(readFileSync(join(here, 'snapshot.fixture.json'), 'utf8'));

/** Anything the views poke at in the DOM: every property is another stub, calls return stubs. */
function stub() {
  const fn = function () {};
  return new Proxy(fn, {
    get(_t, k) {
      if (k === Symbol.toPrimitive) return () => '';
      if (k === 'then') return undefined; // not a promise
      if (k === 'classList') return { add() {}, remove() {}, toggle() {}, contains: () => false };
      if (k === 'dataset' || k === 'style') return {};
      return stub();
    },
    set() { return true; },
    apply() { return stub(); },
  });
}

function load() {
  const store = new Map();
  const document = {
    querySelector: () => stub(), querySelectorAll: () => [], getElementById: () => stub(),
    createElement: () => stub(), addEventListener() {}, documentElement: stub(), body: stub(), activeElement: null,
  };
  const ctx = {
    console, setTimeout, clearTimeout, setInterval: () => 0, clearInterval() {}, Intl, URL, URLSearchParams, TextEncoder, TextDecoder,
    document,
    localStorage: { getItem: (k) => store.get(k) ?? null, setItem: (k, v) => store.set(k, String(v)), removeItem: (k) => store.delete(k) },
    location: { hash: '', protocol: 'http:', hostname: '127.0.0.1', host: '127.0.0.1:8770', origin: 'http://127.0.0.1:8770', href: 'http://127.0.0.1:8770/' },
    navigator: { clipboard: {} },
    matchMedia: () => ({ matches: false, addEventListener() {} }),
    fetch: () => Promise.reject(new Error('offline in tests')),
    addEventListener() {},
  };
  ctx.window = ctx; ctx.globalThis = ctx; ctx.self = ctx;
  vm.createContext(ctx);
  for (const f of ['config.js', 'data.js', 'knowledge.js']) vm.runInContext(readFileSync(join(web, f), 'utf8'), ctx, { filename: f });
  // Everything up to the boot call, then hand the internals to the test instead of booting
  const src = readFileSync(join(web, 'app.js'), 'utf8');
  const cut = src.lastIndexOf('\nboot();');
  assert.ok(cut > 0, 'app.js must end its setup with a top-level boot(); call');
  vm.runInContext(src.slice(0, cut) + '\nglobalThis.__bl = { S, Views };', ctx, { filename: 'app.js' });
  return ctx.__bl;
}

const BAD = [/\bundefined\b/, /\bNaN\b/, /\[object Object\]/, /Invalid Date/];

function check(name, html) {
  assert.equal(typeof html, 'string', `${name} must render a string`);
  // ignore script/style blocks, where these words can be legitimate code
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, '');
  for (const re of BAD) {
    const m = text.match(re);
    assert.ok(!m, `${name} rendered "${m?.[0]}" near: …${text.slice(Math.max(0, m?.index - 120), m?.index + 60)}…`);
  }
}

test('every view renders the phone snapshot without holes', () => {
  const { S, Views } = load();
  S.snap = fixture;
  S.mode = 'phone';
  const names = Object.keys(Views);
  assert.ok(names.length > 15, 'views found');
  for (const name of names) {
    S.view = name; S.sub = '';
    let html;
    assert.doesNotThrow(() => { html = Views[name](); }, `${name} threw`);
    check(name, html);
  }
});

/**
 * Wraps the snapshot so every key a view reads is recorded as a path like `vehicle.trips[].mpg`.
 * Reads of keys the phone doesn't send are the drift this file exists to catch: the views fall
 * back to "—" or skip a panel, so nothing looks broken — the data is just silently gone.
 */
function recording(root) {
  const missing = new Set();
  const skip = (k) => typeof k === 'symbol' || k === 'toJSON' || k === 'then' || k === 'constructor';
  const wrap = (v, path) => {
    if (v === null || typeof v !== 'object') return v;
    const isArr = Array.isArray(v);
    return new Proxy(v, {
      get(t, k, r) {
        if (skip(k)) return Reflect.get(t, k, r);
        if (isArr) {
          if (/^\d+$/.test(k)) return wrap(t[k], path + '[]');
          return Reflect.get(t, k, r); // length, map, filter…
        }
        if (!(k in t) && !(k in Object.prototype)) missing.add(path ? `${path}.${k}` : k);
        return wrap(Reflect.get(t, k, r), path ? `${path}.${k}` : k);
      },
      has(t, k) { if (!isArr && typeof k === 'string' && !(k in t)) missing.add(path ? `${path}.${k}` : k); return k in t; },
    });
  };
  return { snap: wrap(root, ''), missing };
}

/**
 * Keys the desktop probes on purpose although this fixture doesn't carry them, each with why.
 * Keep this short: anything else a view reads must exist in the phone's snapshot.
 */
const OPTIONAL = new Map([
  ['vehicle.error', 'set by the phone only when the car section failed to build'],
  ['info.weather', 'only present once the phone has fetched a forecast'],
  ['info.cloud.error', 'null when sync is healthy (present as null — kept for older phones)'],
]);

test('desktop reads only fields the phone sends', () => {
  const { S, Views } = load();
  const { snap, missing } = recording(fixture);
  S.snap = snap; S.mode = 'phone';
  for (const name of Object.keys(Views)) { S.view = name; S.sub = ''; Views[name](); }
  const unexpected = [...missing].filter((p) => !OPTIONAL.has(p)).sort();
  assert.deepEqual(unexpected, [], 'The desktop reads snapshot fields the phone does not send (renamed or removed on the phone?).\n' +
    'Fix the view, or the phone (then regenerate the fixture with SnapshotContractTest), or add a deliberate probe to OPTIONAL.');
});

test('views that only read the snapshot show its data', () => {
  const { S, Views } = load();
  S.snap = fixture; S.mode = 'phone';
  const shows = (view, text) => { S.view = view; S.sub = ''; assert.ok(Views[view]().includes(text), `${view} should show "${text}"`); };
  shows('facility', 'Generator 1');
  shows('timeline', 'WO P2: Leak');
  shows('health', 'Last backup 9 days ago');
  shows('garage', 'Work lot');
  shows('brainstorm', 'Projects');
  shows('tasks', 'Leak in room 214');
});

test('views survive having no snapshot yet (first launch)', () => {
  const { S, Views } = load();
  S.snap = null; S.mode = 'offline';
  for (const name of Object.keys(Views)) {
    S.view = name; S.sub = '';
    assert.doesNotThrow(() => Views[name](), `${name} threw with no snapshot`);
  }
});
